insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'ban_than', 'Người mang số 1 thường được mô tả là tự quyết, thích mở đường và khó chịu khi phải chờ người khác cho phép.', 'Dễ biến độc lập thành cô lập; nghe góp ý như bị thách thức.', 'Thử giao trọn một việc nhỏ cho người khác và không can thiệp đến khi xong.', 'Lần gần nhất bạn đổi ý vì một lời góp ý của người khác là khi nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'tinh_yeu', 'Trong tình cảm, số 1 thường chủ động, thích dẫn nhịp và cần được tôn trọng khoảng riêng.', 'Dễ quyết thay cho cả hai, coi nhu cầu của người kia là thứ cần ''xử lý''.', 'Hỏi người ấy ''em/anh muốn thế nào?'' trước khi đưa ra phương án của mình.', 'Trong mối quan hệ gần nhất, ai là người hay nhượng bộ hơn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'gia_dinh', 'Trong gia đình, số 1 hay nhận vai người mở lối: đi xa sớm, tự lập sớm, hoặc là người quyết việc lớn.', 'Dễ va chạm với người lớn tuổi vì không chịu làm theo nếp cũ.', 'Chọn một việc nhà bạn để người khác làm theo cách của họ, dù bạn thấy chưa tối ưu.', 'Bạn có đang dùng sự độc lập để né những cuộc trò chuyện khó trong nhà?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'con_cai', 'Là cha mẹ, số 1 thường dạy con tự lập sớm và đặt kỳ vọng rõ ràng.', 'Dễ áp đặt lộ trình, ít chừa chỗ cho con thử và sai theo cách của con.', 'Để con tự chọn một việc trong tuần (môn năng khiếu, cách sắp phòng) và giữ lời không can.', 'Lần gần nhất con làm khác ý bạn mà kết quả vẫn ổn là khi nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'tre_em', 'Trẻ mang số 1 thường thích tự làm, hay nói ''con tự làm'', dễ bực khi bị làm hộ.', 'Có thể bướng, khó chấp nhận thua, dễ cáu khi không được làm chủ.', 'Cho trẻ những lựa chọn có giới hạn (''áo xanh hay áo đỏ'') thay vì ra lệnh.', 'Trẻ có thật sự bướng, hay chỉ đang cần được tự quyết một phần?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'su_nghiep', 'Số 1 thường hợp vai trò khởi xướng: mở dự án mới, dẫn nhóm nhỏ, làm việc có quyền tự quyết.', 'Dễ chán việc lặp lại; khó làm dưới người quản lý chi li.', 'Khi chọn việc, hỏi rõ mức tự chủ bạn có — với số 1, điều đó quan trọng không kém lương.', 'Bạn bỏ việc gần nhất vì công việc, hay vì không được tự quyết?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'tai_chinh', 'Với tiền, số 1 thường thích tự kiếm, tự quản, ngại phụ thuộc tài chính vào ai.', 'Dễ quyết chi lớn theo cảm hứng khởi đầu mà không tính đường lùi.', 'Đặt quy tắc 48 giờ cho mọi khoản chi lớn hơn một mức bạn tự chọn.', 'Khoản đầu tư gần nhất của bạn có ai phản biện trước khi bạn xuống tiền không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'hoc_tap', 'Số 1 thường học tốt khi được tự chọn hướng và tự đặt mục tiêu.', 'Dễ bỏ môn không thích, ngại hỏi vì sợ lộ chỗ chưa biết.', 'Chia môn khó thành mục tiêu nhỏ do chính bạn đặt, tự chấm điểm mỗi tuần.', 'Bạn né hỏi thầy cô/bạn bè vì không hiểu, hay vì không muốn bị xem là không hiểu?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'suc_khoe', 'Số 1 thường dồn năng lượng vào mục tiêu và quên nghỉ cho tới khi kiệt.', 'Căng thẳng dễ thành cáu gắt, muốn tự gánh hết.', 'Coi giờ nghỉ là một mục tiêu có lịch, không phải phần thưởng khi xong việc.', 'Tuần này bạn đã nghỉ thật sự (không điện thoại, không việc) bao nhiêu giờ?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'ban_be_xa_hoi', 'Trong nhóm bạn, số 1 thường là người rủ, người chốt kế hoạch.', 'Dễ khiến người khác thấy bị lấn át, ít được góp ý thật.', 'Trong lần hẹn tới, để người khác chọn địa điểm và thời gian.', 'Bạn có người bạn nào dám nói ''không'' với bạn mà vẫn thân?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (1, 'cuoc_song', 'Số 1 thường thích tự sắp đặt không gian và nhịp sống của mình, không chịu cảnh ở ghép lâu.', 'Dễ đổi chỗ ở hoặc kế hoạch lớn chỉ vì muốn ''bắt đầu lại''.', 'Trước khi chuyển đổi lớn, viết ra điều bạn đang chạy khỏi và điều bạn đang chạy tới.', 'Lần ''làm lại từ đầu'' gần nhất của bạn đã giải quyết được điều gì?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'ban_than', 'Số 2 thường được mô tả là tinh ý, đọc được không khí, ưu tiên sự hoà thuận.', 'Dễ nuốt ý kiến của mình để giữ êm, rồi tích tụ tủi thân.', 'Tập nói một câu ''tôi nghĩ khác'' mỗi tuần, ở việc nhỏ.', 'Lần gần nhất bạn nói ''không'' thẳng, không giải thích dài dòng?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'tinh_yeu', 'Trong tình yêu, số 2 thường tận tuỵ, nhớ chi tiết nhỏ, cần cảm giác được gắn bó.', 'Dễ đánh mất mình trong mối quan hệ, sợ bị bỏ rơi nên chiều quá mức.', 'Giữ một thói quen riêng (bạn bè, sở thích) không phụ thuộc người yêu.', 'Nếu người ấy rời đi, bạn còn những gì là của riêng mình?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'gia_dinh', 'Số 2 hay là người hoà giải, người ''giữ lửa'' trong nhà.', 'Dễ ôm cảm xúc của cả nhà, đứng giữa hai phía rồi kiệt sức.', 'Khi hai người thân mâu thuẫn, khuyến khích họ nói trực tiếp với nhau thay vì qua bạn.', 'Bạn đang làm cầu nối cho ai, và họ có thật sự cần bạn làm vậy?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'con_cai', 'Là cha mẹ, số 2 thường dịu dàng, nhạy với cảm xúc của con.', 'Dễ khó đặt giới hạn, sợ con buồn nên nhượng bộ.', 'Chọn một quy tắc gia đình và giữ nó nhất quán dù con khóc.', 'Bạn nhượng bộ con vì con cần, hay vì bạn không chịu được con buồn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'tre_em', 'Trẻ số 2 thường nhạy cảm, để ý nét mặt người lớn, thích chơi cùng hơn chơi một mình.', 'Dễ tủi thân, khó nói ra điều mình muốn.', 'Hỏi trẻ bằng câu có lựa chọn cảm xúc (''con thấy buồn hay giận?'') để trẻ tập gọi tên.', 'Trẻ im lặng vì ổn, hay vì chưa biết nói ra?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'su_nghiep', 'Số 2 thường làm tốt vai trò phối hợp, hỗ trợ, chăm sóc khách hàng, làm cầu nối giữa các nhóm.', 'Dễ làm nhiều nhưng không đòi ghi nhận; né vai trò cần va chạm.', 'Ghi lại đóng góp của mình mỗi tuần để có dữ liệu khi đánh giá.', 'Sếp có biết cụ thể bạn đã làm gì trong quý này không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'tai_chinh', 'Với tiền, số 2 thường cẩn thận, thích tích luỹ dần, ưu tiên an toàn.', 'Dễ cho người thân vay vì ngại từ chối.', 'Đặt sẵn một hạn mức cho vay/giúp đỡ mỗi năm, vượt thì trả lời ''để mình xem lại''.', 'Khoản tiền bạn cho mượn gần nhất, bạn đồng ý vì muốn hay vì ngại?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'hoc_tap', 'Số 2 thường học tốt khi có bạn học, có người hướng dẫn tận tình.', 'Dễ mất tự tin khi bị so sánh, sợ phát biểu sai.', 'Tìm một bạn học cùng cố định; giải thích bài cho nhau.', 'Bạn hiểu bài thật, hay chỉ gật đầu cho khỏi phiền người giảng?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'suc_khoe', 'Số 2 thường hấp thụ căng thẳng của người xung quanh.', 'Dễ mệt vì cảm xúc hơn vì việc.', 'Sau những cuộc gặp nặng nề, dành 15 phút một mình trước khi làm việc khác.', 'Nỗi mệt hôm nay là của bạn, hay bạn đang mang hộ ai?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'ban_be_xa_hoi', 'Số 2 thường là người bạn biết lắng nghe, được tin để kể chuyện.', 'Dễ bị lợi dụng lòng tốt; khó rời bỏ tình bạn một chiều.', 'Để ý tỉ lệ cho–nhận trong từng mối quan hệ, nói ra khi lệch quá lâu.', 'Ai là người lắng nghe bạn như cách bạn lắng nghe họ?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (2, 'cuoc_song', 'Số 2 thường cần không gian ấm, ổn định, gần người thân.', 'Dễ ngại thay đổi môi trường dù nơi cũ không còn hợp.', 'Thử thay đổi nhỏ trước (góc làm việc, lịch cuối tuần) trước khi nghĩ đến thay đổi lớn.', 'Bạn ở lại vì thích nơi này, hay vì sợ nơi khác?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'ban_than', 'Số 3 thường được mô tả là giàu ý tưởng, nói chuyện có duyên, cần được thể hiện.', 'Dễ tản mạn, bắt đầu nhiều hơn hoàn thành; dùng vui vẻ để né chuyện sâu.', 'Chọn một dự án và theo tới cùng trước khi mở cái mới.', 'Bạn có dự án nào theo tới cùng dù đã hết hứng?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'tinh_yeu', 'Trong tình yêu, số 3 thường lãng mạn, vui, thích được khen và được chú ý.', 'Dễ chán khi hết giai đoạn mới mẻ; né nói chuyện nghiêm túc.', 'Tạo ''điều mới'' bên trong mối quan hệ (trải nghiệm chung) thay vì tìm ở người mới.', 'Bạn chán người ấy, hay chán giai đoạn quen thuộc của mọi mối quan hệ?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'gia_dinh', 'Số 3 hay là người mang tiếng cười, làm không khí gia đình nhẹ đi.', 'Dễ đùa cho qua những chuyện cần nói thẳng.', 'Khi nhà có chuyện, thử nói một câu nghiêm túc trước khi pha trò.', 'Có chuyện gì trong nhà bạn vẫn đang cười cho qua?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'con_cai', 'Là cha mẹ, số 3 thường chơi cùng con giỏi, khuyến khích con sáng tạo.', 'Dễ thiếu nề nếp, hứa với con nhiều mà quên làm.', 'Chỉ hứa điều bạn ghi được vào lịch.', 'Con bạn có nhớ lời hứa nào của bạn chưa được thực hiện?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'tre_em', 'Trẻ số 3 thường hoạt ngôn, thích vẽ, hát, kể chuyện, thích được khen trước người khác.', 'Dễ mất tập trung, bỏ dở bài tập.', 'Chia việc thành phần ngắn, khen quá trình hơn khen kết quả.', 'Trẻ lơ là vì lười, hay vì việc quá dài so với sức tập trung của trẻ?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'su_nghiep', 'Số 3 thường hợp việc cần diễn đạt: viết, nói, thiết kế, truyền thông, bán hàng, giảng dạy.', 'Dễ bỏ ngang khi phần việc chuyển sang giai đoạn chi tiết, nhàm.', 'Ghép cặp với người giỏi hoàn thiện; bạn lo ý tưởng, họ lo về đích.', 'Trong năm qua, bao nhiêu ý tưởng của bạn đã thành sản phẩm thật?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'tai_chinh', 'Với tiền, số 3 thường rộng rãi, tiêu cho trải nghiệm và người khác.', 'Dễ chi theo cảm hứng, khó theo dõi chi tiêu.', 'Tự động chuyển một phần thu nhập vào tài khoản tiết kiệm ngay ngày nhận lương.', 'Tháng trước bạn tiêu bao nhiêu cho những thứ không nhớ đã mua?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'hoc_tap', 'Số 3 thường học nhanh qua trao đổi, trình bày, học bằng hình ảnh.', 'Dễ học lướt, giỏi nói hơn giỏi làm bài viết chi tiết.', 'Sau mỗi bài, tự giảng lại cho người khác trong 5 phút.', 'Bạn hiểu sâu hay chỉ đủ để nói hay về nó?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'suc_khoe', 'Số 3 thường nạp năng lượng qua giao lưu và sáng tạo.', 'Dễ giấu buồn sau vẻ vui; thức khuya vì hứng.', 'Có một người để kể thật lòng, không cần diễn vui.', 'Lần gần nhất bạn để ai thấy mình buồn là khi nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'ban_be_xa_hoi', 'Số 3 thường có nhiều bạn, là tâm điểm trong nhóm.', 'Dễ rộng mà nông; nói trước quên sau.', 'Chọn hai, ba người để đầu tư tình bạn sâu.', 'Nếu gặp chuyện lúc nửa đêm, bạn gọi được ai?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (3, 'cuoc_song', 'Số 3 thường thích không gian có màu sắc, có chỗ cho sở thích sáng tạo.', 'Dễ sống bừa bộn, nhiều dự án dang dở chiếm chỗ.', 'Mỗi tháng dọn một góc và kết thúc (hoặc bỏ hẳn) một dự án dang dở.', 'Đồ dang dở trong nhà bạn đang chờ bạn, hay chờ bạn dám bỏ?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'ban_than', 'Số 4 thường được mô tả là chắc chắn, có nguyên tắc, thích làm theo kế hoạch.', 'Dễ cứng nhắc, lo lắng khi mọi thứ thay đổi đột ngột.', 'Mỗi tháng thử một thay đổi nhỏ có chủ ý trong thói quen.', 'Lần gần nhất bạn phá bỏ một hệ thống mình đã dựng là khi nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'tinh_yeu', 'Trong tình yêu, số 4 thường chung thuỷ, thể hiện tình cảm bằng việc làm hơn lời nói.', 'Dễ khô khan, coi lãng mạn là thừa; khó mở lòng nhanh.', 'Nói thành lời một điều bạn trân trọng ở người ấy mỗi tuần.', 'Người ấy có biết bạn thương họ, hay chỉ thấy bạn làm việc?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'gia_dinh', 'Số 4 thường là trụ cột lo phần thực tế: nhà cửa, giấy tờ, kế hoạch.', 'Dễ nghiêm khắc, đặt nhiều quy tắc làm người thân thấy ngột ngạt.', 'Hỏi người nhà quy tắc nào họ thấy không cần nữa.', 'Quy tắc nào trong nhà tồn tại vì thói quen hơn vì lý do?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'con_cai', 'Là cha mẹ, số 4 thường tạo nề nếp tốt, lịch sinh hoạt rõ ràng.', 'Dễ khắt khe, ít chỗ cho sự ngẫu hứng và sai lầm của con.', 'Dành một buổi mỗi tuần không có lịch, để con dẫn dắt hoạt động.', 'Con bạn có dám kể với bạn khi làm sai không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'tre_em', 'Trẻ số 4 thường thích sự ổn định, làm việc tỉ mỉ, thích lắp ráp, sắp xếp.', 'Dễ bực khi kế hoạch đổi, chậm thích nghi với môi trường mới.', 'Báo trước thay đổi, giải thích lý do bằng lời đơn giản.', 'Trẻ chậm, hay chỉ cần thêm thời gian để yên tâm?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'su_nghiep', 'Số 4 thường làm tốt việc cần hệ thống: kỹ thuật, kế toán, vận hành, quản lý dự án, xây dựng.', 'Dễ làm việc chăm mà không hỏi việc đó dẫn tới đâu; ngại đổi hướng.', 'Mỗi quý tự hỏi: công việc này còn phục vụ mục tiêu dài hạn của mình không?', 'Bạn đang làm tốt việc đúng, hay làm đúng việc tốt?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'tai_chinh', 'Với tiền, số 4 thường tiết kiệm, có kế hoạch, thích tài sản hữu hình.', 'Dễ quá dè dặt, lỡ cơ hội vì sợ rủi ro; khó tiêu cho bản thân.', 'Dành một khoản nhỏ cố định cho niềm vui cá nhân, không cần lý do.', 'Bạn tiết kiệm để làm gì — và bao giờ thì ''đủ''?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'hoc_tap', 'Số 4 thường học chắc, theo lộ trình, ôn bài đều đặn.', 'Dễ học vẹt đúng khuôn, lúng túng với dạng bài mới.', 'Mỗi tuần làm một bài theo cách khác sách giáo khoa.', 'Bạn giải được vì hiểu, hay vì đã gặp dạng này?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'suc_khoe', 'Số 4 thường có thói quen đều đặn, chịu được áp lực dài.', 'Dễ ôm việc, cố quá sức vì trách nhiệm; căng cơ, căng thẳng tích tụ.', 'Lên lịch vận động như một việc bắt buộc trong kế hoạch tuần.', 'Cơ thể bạn đã nhắc bạn nghỉ bao nhiêu lần trước khi bạn nghe?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'ban_be_xa_hoi', 'Số 4 thường ít bạn nhưng bền, đáng tin, giữ lời.', 'Dễ bị thấy khó gần, nghiêm quá.', 'Chủ động rủ một người bạn làm việc gì đó không có mục đích.', 'Bạn bè biết bạn đáng tin, nhưng có biết bạn vui thế nào không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (4, 'cuoc_song', 'Số 4 thường thích nhà ngăn nắp, ổn định, ở lâu một chỗ.', 'Dễ ngại đi xa, ngại thử điều mới trong đời sống.', 'Mỗi năm đi một nơi chưa từng đến.', 'Lần cuối bạn làm điều gì lần đầu tiên là khi nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'ban_than', 'Số 5 thường được mô tả là thích tự do, ưa trải nghiệm, thích nghi nhanh.', 'Dễ bốc đồng, bỏ đi khi vừa gặp khó; sợ bị ràng buộc.', 'Trước khi rời một việc, ở lại thêm một chu kỳ (một tháng, một dự án) rồi mới quyết.', 'Bạn đã ở đâu đủ lâu để thấy hậu quả dài hạn của việc mình làm?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'tinh_yeu', 'Trong tình yêu, số 5 thường cuốn hút, thích phiêu lưu, cần không khí mới mẻ.', 'Dễ ngại cam kết, chán khi mối quan hệ vào nhịp đều.', 'Nói rõ với người ấy bạn cần bao nhiêu không gian, thay vì biến mất.', 'Bạn cần tự do khỏi người ấy, hay khỏi nỗi sợ bị giữ chân?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'gia_dinh', 'Số 5 hay là người đi xa, người mang chuyện mới về nhà.', 'Dễ vắng mặt lúc gia đình cần; thấy bổn phận là gánh nặng.', 'Chọn một việc gia đình cố định bạn luôn có mặt (bữa cơm tuần, ngày giỗ).', 'Người nhà có thể trông cậy bạn vào việc gì?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'con_cai', 'Là cha mẹ, số 5 thường cho con trải nghiệm phong phú, cởi mở.', 'Dễ thiếu nhất quán, lúc sát lúc buông.', 'Giữ vài nếp cố định (giờ ngủ, giờ ăn) để con có điểm tựa.', 'Con bạn biết chắc điều gì sẽ luôn giống nhau mỗi ngày?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'tre_em', 'Trẻ số 5 thường hiếu động, tò mò, thích khám phá, dễ chán.', 'Khó ngồi yên, hay đổi sở thích.', 'Cho trẻ vận động trước giờ học; thay đổi hình thức học thường xuyên.', 'Trẻ không chịu học, hay chưa được học theo cách vận động?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'su_nghiep', 'Số 5 thường hợp việc đa dạng, di chuyển, giao tiếp: bán hàng, du lịch, truyền thông, khởi nghiệp.', 'Dễ nhảy việc liên tục, hồ sơ nhiều khởi đầu ít thành tựu.', 'Tìm vai trò có biến hoá bên trong (dự án mới) thay vì đổi công ty.', 'Lần nhảy việc gần nhất bạn chạy tới điều gì, hay chỉ chạy khỏi điều gì?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'tai_chinh', 'Với tiền, số 5 thường kiếm nhanh tiêu nhanh, thích cơ hội mới.', 'Dễ mạo hiểm theo trào lưu, đầu tư vì hứng.', 'Chỉ dùng một phần nhỏ, định trước, cho các khoản ''thử vận''.', 'Khoản mạo hiểm gần nhất, bạn đã hiểu nó trước khi vào tiền chưa?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'hoc_tap', 'Số 5 thường học qua trải nghiệm, thực hành, đi và làm.', 'Dễ bỏ giữa khoá học, học nhiều thứ nhưng nông.', 'Gắn việc học với một dự án thực tế có hạn chót.', 'Kỹ năng nào bạn đã học đủ sâu để người khác trả tiền cho nó?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'suc_khoe', 'Số 5 thường cần vận động, cần thay đổi để thấy sống động.', 'Dễ sinh hoạt thất thường; tìm kích thích để thoát chán.', 'Chọn môn vận động có nhiều biến thể (leo núi, nhảy, bơi) để giữ được đều.', 'Bạn tìm niềm vui, hay tìm thứ để khỏi phải ngồi yên với mình?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'ban_be_xa_hoi', 'Số 5 thường quen biết rộng, dễ bắt chuyện, hợp nhiều kiểu người.', 'Dễ biến mất rồi xuất hiện, bạn bè khó dựa.', 'Giữ liên lạc đều với vài người thân nhất dù đang ở đâu.', 'Ai sẽ nhận ra nếu bạn biến mất một tháng?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (5, 'cuoc_song', 'Số 5 thường thích đi, thích đổi chỗ, sống được ở nhiều nơi.', 'Dễ không có gốc rễ, chuyển đi khi thấy bí.', 'Trước khi chuyển, liệt kê điều ở nơi mới giải quyết được mà nơi cũ không.', 'Nơi mới sẽ khác, nhưng bạn mang theo gì cũ?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'ban_than', 'Số 6 thường được mô tả là giàu trách nhiệm, hay chăm lo, coi trọng gia đình và cái đẹp.', 'Dễ kiểm soát dưới vỏ quan tâm, hy sinh rồi oán.', 'Hỏi ''bạn có cần mình giúp không?'' trước khi giúp.', 'Bạn có để người khác tự xử lý việc của họ mà không can vào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'tinh_yeu', 'Trong tình yêu, số 6 thường chu đáo, muốn xây tổ ấm, sẵn sàng cho đi nhiều.', 'Dễ bao bọc thành kiểm soát; kỳ vọng người kia đáp lại đúng cách mình cho.', 'Hỏi người ấy họ cảm thấy được yêu qua điều gì, thay vì đoán.', 'Bạn cho đi vì người ấy cần, hay vì bạn cần được cần?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'gia_dinh', 'Số 6 thường là người chăm cả nhà, gánh việc cha mẹ, anh em.', 'Dễ ôm hết, rồi kiệt và trách người khác vô tâm.', 'Chia rõ việc nhà, chấp nhận người khác làm chưa được như bạn.', 'Việc nào bạn đang làm hộ người thân mà họ tự làm được?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'con_cai', 'Là cha mẹ, số 6 thường tận tuỵ, chăm con chu đáo.', 'Dễ bảo bọc quá mức, khó để con tự trải nghiệm hậu quả nhỏ.', 'Để con tự chịu một hậu quả nhỏ (quên đồ, trễ giờ) mà không cứu.', 'Con bạn đã tự giải quyết được vấn đề gì mà không cần bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'tre_em', 'Trẻ số 6 thường tình cảm, thích chăm em, chăm thú, muốn làm người lớn vui.', 'Dễ nhận lỗi về mình, lo lắng khi bố mẹ buồn.', 'Nói với trẻ rằng chuyện người lớn không phải trách nhiệm của trẻ.', 'Trẻ ngoan vì vui, hay vì sợ làm người lớn buồn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'su_nghiep', 'Số 6 thường hợp việc chăm sóc, giáo dục, y tế, tư vấn, dịch vụ, thiết kế không gian.', 'Dễ nhận quá nhiều việc của người khác, khó đòi quyền lợi.', 'Đặt giới hạn giờ làm và phạm vi việc rõ ràng với sếp và khách.', 'Bạn làm thêm việc vì được giao, hay vì không nỡ từ chối?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'tai_chinh', 'Với tiền, số 6 thường chi cho gia đình, cho người thân trước bản thân.', 'Dễ gánh tài chính của cả nhà, bỏ quên quỹ riêng.', 'Lập quỹ riêng cho mình trước khi chi cho người khác.', 'Nếu bạn ngừng gánh, ai trong nhà sẽ tự đứng được?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'hoc_tap', 'Số 6 thường học tốt môn gắn với con người, nghệ thuật, ứng dụng giúp người.', 'Dễ bỏ việc học của mình để lo cho người khác.', 'Giữ giờ học như một cam kết với chính mình, không nhường.', 'Lần gần nhất bạn hoãn việc của mình vì người khác là khi nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'suc_khoe', 'Số 6 thường khoẻ khi thấy người thân ổn, dễ bệnh khi lo cho người khác.', 'Dễ bỏ bê bản thân, căng thẳng vì trách nhiệm.', 'Ghi vào lịch một việc chăm sóc bản thân như chăm người khác.', 'Ai chăm sóc bạn khi bạn mệt?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'ban_be_xa_hoi', 'Số 6 thường là người bạn chu đáo, nhớ sinh nhật, hay hỏi han.', 'Dễ thành ''mẹ'' của nhóm, mệt vì lo cho mọi người.', 'Cho phép mình là người được chăm trong một lần gặp.', 'Bạn có người bạn nào hỏi han bạn trước không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (6, 'cuoc_song', 'Số 6 thường chăm chút nhà cửa, thích không gian đẹp, ấm cúng.', 'Dễ cầu toàn về nhà cửa, khó chịu khi người khác làm khác.', 'Chọn một góc nhà để người thân tự bày theo ý họ.', 'Ngôi nhà đẹp để ai thấy, hay để ai sống?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'ban_than', 'Số 7 thường được mô tả là sâu sắc, thích phân tích, cần thời gian một mình.', 'Dễ xa cách, hoài nghi, phân tích thay vì hành động.', 'Đặt hạn chót cho việc suy nghĩ; quá hạn thì chọn phương án tốt nhất đang có.', 'Lần gần nhất bạn quyết mà chưa đủ dữ liệu, và ổn với điều đó?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'tinh_yeu', 'Trong tình yêu, số 7 thường kén chọn, cần kết nối trí tuệ, cần khoảng lặng.', 'Dễ khép kín, khiến người kia thấy bị đẩy ra; khó nói cảm xúc.', 'Khi cần ở một mình, nói trước ''mình cần yên một lúc, không phải giận''.', 'Người ấy có hiểu sự im lặng của bạn không, hay đang đoán?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'gia_dinh', 'Số 7 hay là người ''khác'' trong nhà, sống nội tâm, ít chia sẻ.', 'Dễ bị thấy lạnh nhạt, xa cách với người thân.', 'Chia sẻ một điều bạn đang nghĩ với một người trong nhà mỗi tuần.', 'Gia đình biết gì về thế giới bên trong của bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'con_cai', 'Là cha mẹ, số 7 thường khuyến khích con đặt câu hỏi, đọc sách, suy nghĩ độc lập.', 'Dễ ít thể hiện tình cảm, thiên về lý lẽ.', 'Ôm con, nói ''bố/mẹ thương con'' không cần lý do.', 'Con bạn cảm được bạn thương, hay chỉ nghe bạn giảng?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'tre_em', 'Trẻ số 7 thường trầm, thích tìm hiểu, hỏi ''tại sao'', thích chơi một mình.', 'Dễ bị cho là khó gần, ít bạn.', 'Tôn trọng giờ riêng của trẻ; giới thiệu bạn cùng sở thích thay vì ép chơi đông.', 'Trẻ cô đơn, hay chỉ đang thích yên tĩnh?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'su_nghiep', 'Số 7 thường hợp việc chuyên sâu: nghiên cứu, phân tích dữ liệu, kỹ thuật, luật, viết, chuyên gia.', 'Dễ cầu toàn, ngại trình bày, để người khác nhận công.', 'Tập trình bày kết quả sớm, dù chưa hoàn hảo.', 'Ý tưởng hay nhất của bạn năm nay đã có ai nghe chưa?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'tai_chinh', 'Với tiền, số 7 thường cân nhắc kỹ, thích tìm hiểu trước khi quyết.', 'Dễ phân tích mãi không hành động; hoài nghi mọi lời khuyên.', 'Chọn một nguyên tắc đơn giản (vd tiết kiệm tự động) và làm ngay.', 'Bạn đã nghiên cứu đủ, hay đang dùng nghiên cứu để trì hoãn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'hoc_tap', 'Số 7 thường học sâu, tự học giỏi, thích hiểu bản chất.', 'Dễ sa vào chi tiết, học mãi không thi, ngại học nhóm.', 'Đặt mốc kiểm tra ngoài (thi, chứng chỉ, sản phẩm) cho việc tự học.', 'Bạn học để biết hay để dùng?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'suc_khoe', 'Số 7 thường cần yên tĩnh để hồi phục, dễ căng đầu óc.', 'Dễ mất ngủ vì nghĩ nhiều, cô lập khi buồn.', 'Có hoạt động tay chân đều đặn để đầu óc nghỉ.', 'Khi buồn bạn tìm đến ai, hay chỉ tìm đến suy nghĩ của mình?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'ban_be_xa_hoi', 'Số 7 thường ít bạn, chọn lọc, thích trò chuyện sâu.', 'Dễ bị thấy kiêu, khó tiếp cận.', 'Chủ động hỏi han trước một người bạn mỗi tháng.', 'Có ai biết bạn đang trải qua điều gì lúc này?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (7, 'cuoc_song', 'Số 7 thường thích nơi yên tĩnh, gần thiên nhiên, có góc riêng.', 'Dễ thu mình, sống tách khỏi cộng đồng.', 'Giữ một hoạt động cộng đồng nhỏ, đều đặn.', 'Sự yên tĩnh đang nuôi bạn, hay đang che bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'ban_than', 'Số 8 thường được mô tả là tham vọng, thực tế, có khả năng tổ chức và quản lý nguồn lực.', 'Dễ đo giá trị bản thân bằng thành tích, tiền, quyền; khó thừa nhận yếu.', 'Mỗi tuần làm một việc không vì kết quả.', 'Nếu mất danh hiệu và thu nhập, bạn còn thấy mình giá trị ở điểm nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'tinh_yeu', 'Trong tình yêu, số 8 thường bảo vệ, lo toan vật chất, muốn người ấy được đầy đủ.', 'Dễ coi lo tiền là đủ yêu; khó mềm mỏng, hay ''quản lý'' người yêu.', 'Dành thời gian có mặt trọn vẹn, không điện thoại, không bàn việc.', 'Người ấy cần tiền của bạn, hay cần bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'gia_dinh', 'Số 8 thường là người lo kinh tế, ra quyết định lớn trong nhà.', 'Dễ gia trưởng, dùng tiền để có tiếng nói.', 'Để người thân tự quyết những việc trong phần của họ.', 'Người nhà nghe bạn vì đồng ý, hay vì bạn là người trả tiền?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'con_cai', 'Là cha mẹ, số 8 thường dạy con tính kỷ luật, tự lập tài chính, đặt mục tiêu.', 'Dễ đặt kỳ vọng thành tích quá cao, đo con bằng điểm số.', 'Khen nỗ lực và cách con làm, không chỉ kết quả.', 'Con bạn nghĩ bạn thương nó vì nó là nó, hay vì nó giỏi?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'tre_em', 'Trẻ số 8 thường thích làm chủ, thích thắng, hiểu giá trị đồ vật sớm.', 'Dễ hiếu thắng, khó chấp nhận thua, hay ra lệnh cho bạn.', 'Cho trẻ quản lý một khoản tiền nhỏ; chơi trò có thắng thua để tập thua đẹp.', 'Trẻ hiếu thắng, hay đang học cách đo giá trị từ người lớn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'su_nghiep', 'Số 8 thường hợp vai trò quản lý, kinh doanh, tài chính, điều hành, bất động sản.', 'Dễ cuốn vào công việc, hy sinh sức khoẻ và gia đình cho mục tiêu.', 'Đặt mục tiêu phi tài chính song song (sức khoẻ, quan hệ) và đo như KPI.', 'Thành công bạn đang đuổi theo là của bạn, hay của kỳ vọng người khác?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'tai_chinh', 'Với tiền, số 8 thường giỏi nhìn cơ hội, dám đầu tư, xây tài sản.', 'Dễ liều lớn, vay đòn bẩy; mọi thứ quy ra tiền.', 'Luôn có kịch bản thua và quỹ dự phòng trước mỗi quyết định lớn.', 'Nếu thương vụ này thất bại, bạn chịu được mức nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'hoc_tap', 'Số 8 thường học vì mục tiêu rõ ràng, học cái dùng được ngay.', 'Dễ coi thường môn ''không ra tiền''.', 'Học thêm một thứ chỉ vì tò mò.', 'Có điều gì bạn thích học mà không đem lại lợi ích nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'suc_khoe', 'Số 8 thường có sức bền, chịu áp lực lớn.', 'Dễ gồng, bỏ qua dấu hiệu cơ thể cho tới khi đổ bệnh.', 'Khám sức khoẻ định kỳ và nghỉ phép thật, đặt lịch trước.', 'Lần cuối bạn nghỉ phép mà không mở email là khi nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'ban_be_xa_hoi', 'Số 8 thường có mạng lưới quan hệ rộng, được nể trọng.', 'Dễ biến bạn bè thành quan hệ công việc; bạn thật ít.', 'Giữ vài tình bạn không dính dáng làm ăn.', 'Bạn có người bạn nào chẳng giúp gì cho sự nghiệp của bạn không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (8, 'cuoc_song', 'Số 8 thường thích nhà rộng, chất lượng, có vị thế.', 'Dễ sống để thể hiện, chạy theo tiêu chuẩn của người khác.', 'Chọn một thứ trong đời sống chỉ vì bạn thích, không vì nó ''xứng''.', 'Nếu không ai nhìn, bạn muốn sống ở đâu, thế nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'ban_than', 'Số 9 thường được mô tả là bao dung, lý tưởng, nghĩ cho cộng đồng.', 'Dễ ôm việc thiên hạ, buông cái của mình; khó kết thúc chuyện cũ.', 'Chọn một việc lớn để cống hiến, nói không với những việc còn lại.', 'Bạn giúp người khác vì họ cần, hay để khỏi nhìn vào việc của chính mình?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'tinh_yeu', 'Trong tình yêu, số 9 thường rộng lượng, lãng mạn, yêu theo kiểu lý tưởng.', 'Dễ yêu hình ảnh hơn con người thật; khó dứt mối quan hệ đã hết.', 'Liệt kê những điều thật (không phải mong đợi) bạn biết về người ấy.', 'Bạn yêu người ấy, hay yêu người mà bạn hy vọng họ sẽ trở thành?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'gia_dinh', 'Số 9 thường là người rộng lòng, hay lo cho họ hàng, người ngoài.', 'Dễ lo người ngoài hơn người trong nhà.', 'Dành thời gian cho người thân gần nhất trước các việc thiện nguyện.', 'Người trong nhà có thấy bạn dành cho họ như dành cho người ngoài?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'con_cai', 'Là cha mẹ, số 9 thường dạy con lòng tốt, sự bao dung, mở rộng thế giới quan.', 'Dễ kỳ vọng con ''tốt'' theo lý tưởng của mình.', 'Để con được giận, được ích kỷ một chút theo tuổi.', 'Bạn muốn con tốt, hay muốn con giống hình mẫu của bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'tre_em', 'Trẻ số 9 thường giàu cảm xúc, thương người, hay cho đồ chơi.', 'Dễ buồn lâu, nhạy với chuyện bất công.', 'Giúp trẻ làm một việc tốt cụ thể khi trẻ buồn vì chuyện bất công.', 'Trẻ đang buồn cho mình, hay buồn thay người khác?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'su_nghiep', 'Số 9 thường hợp việc có ý nghĩa xã hội: giáo dục, y tế, nghệ thuật, phi lợi nhuận, ngoại giao.', 'Dễ làm vì lý tưởng mà quên thu nhập; khó rời tổ chức dù không còn hợp.', 'Tính rõ mức thu nhập tối thiểu bạn cần trước khi nhận việc ''ý nghĩa''.', 'Sự cống hiến của bạn có đang được đền đáp đủ để bạn đi đường dài?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'tai_chinh', 'Với tiền, số 9 thường hào phóng, dễ cho, ít bám víu.', 'Dễ cho đi quá sức, thiếu tích luỹ cho mình.', 'Tách quỹ cho đi và quỹ của mình, không lấy quỹ này bù quỹ kia.', 'Bạn có đang giúp người khác bằng tiền mà chính bạn cần?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'hoc_tap', 'Số 9 thường học rộng, thích văn hoá, ngôn ngữ, nhân văn.', 'Dễ học dàn trải, thiếu một chuyên môn sâu.', 'Chọn một lĩnh vực chính để đi sâu, phần còn lại để mở rộng.', 'Nếu phải chọn một lĩnh vực trong mười năm tới, đó là gì?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'suc_khoe', 'Số 9 thường nhạy với nỗi đau của người khác.', 'Dễ kiệt vì đồng cảm, mang buồn hộ người khác.', 'Hạn chế tin tức tiêu cực; có nghi thức ''khép lại ngày''.', 'Nỗi buồn hôm nay bắt nguồn từ đời bạn, hay từ màn hình?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'ban_be_xa_hoi', 'Số 9 thường có bạn ở nhiều tầng lớp, dễ được tin cậy.', 'Dễ giữ những tình bạn đã cạn vì ngại kết thúc.', 'Cho phép mình để một mối quan hệ nhạt đi tự nhiên.', 'Tình bạn nào bạn đang giữ vì nghĩa hơn vì vui?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (9, 'cuoc_song', 'Số 9 thường thích đi đây đó, trải nghiệm văn hoá, sống gắn cộng đồng.', 'Dễ giữ đồ cũ, kỷ niệm cũ, khó dọn dẹp.', 'Mỗi mùa cho đi một túi đồ không dùng.', 'Món đồ nào bạn giữ vì kỷ niệm mà thật ra đã xong vai trò?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (11, 'ban_than', 'Số 11 thường được mô tả như số 2 tăng cường: trực giác nhạy, lý tưởng cao, dễ truyền cảm hứng.', 'Dễ căng thẳng thần kinh, tự đặt kỳ vọng quá lớn, dao động giữa tự tin và tự nghi.', 'Kiểm tra trực giác bằng việc nhỏ có kết quả đo được trước khi tin vào nó cho việc lớn.', 'Trực giác của bạn đúng bao nhiêu lần — bạn có ghi lại cả những lần sai không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (11, 'tinh_yeu', 'Trong tình yêu, số 11 thường tìm kết nối tâm hồn, rất nhạy với cảm xúc người kia.', 'Dễ lý tưởng hoá rồi vỡ mộng; bất an khi không được thấu hiểu.', 'Nói ra điều bạn cảm thấy thay vì chờ người ấy tự đoán.', 'Bạn đòi người ấy hiểu bạn, hay đã giúp họ hiểu bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (11, 'gia_dinh', 'Số 11 thường là người cảm nhận không khí gia đình rõ nhất.', 'Dễ bị cuốn vào cảm xúc của người thân, khó tách mình.', 'Tập phân biệt ''điều mình cảm'' và ''điều người khác cảm''.', 'Cảm xúc nào bạn đang mang là của gia đình, không phải của bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (11, 'con_cai', 'Là cha mẹ, số 11 thường thấu cảm, hiểu con không cần nói nhiều.', 'Dễ lo âu thái quá về con; truyền căng thẳng cho con.', 'Chăm sóc sự bình tĩnh của mình trước khi xử lý chuyện của con.', 'Con bạn lo lắng, hay đang phản chiếu nỗi lo của bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
