insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (11, 'suc_khoe', 'Số 11 thường có hệ thần kinh nhạy, dễ căng thẳng.', 'Dễ mất ngủ, lo âu, quá tải giác quan.', 'Hít thở chậm, giảm cà phê, có không gian yên tĩnh mỗi ngày.', 'Tuần này bạn có bao nhiêu phút thật sự yên tĩnh?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (11, 'ban_be_xa_hoi', 'Số 11 thường thu hút người tìm lời khuyên, được xem là ''người hiểu chuyện''.', 'Dễ bị rút năng lượng bởi người hay than.', 'Giới hạn thời gian nghe tâm sự; giới thiệu chuyên gia khi vượt khả năng.', 'Sau khi gặp bạn bè, bạn thấy đầy hơn hay cạn hơn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (11, 'cuoc_song', 'Số 11 thường cần không gian yên, ánh sáng dịu, ít hỗn loạn.', 'Dễ bị môi trường ồn ào làm kiệt sức.', 'Chọn nơi ở và làm việc với tiêu chí yên tĩnh đặt lên cao.', 'Không gian bạn đang sống làm bạn dịu lại hay căng lên?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (22, 'ban_than', 'Số 22 thường được mô tả như số 4 tăng cường: có tầm nhìn lớn và khả năng hiện thực hoá bằng hệ thống.', 'Dễ áp lực phải làm việc lớn; thất vọng về bản thân khi đời chỉ ''bình thường''.', 'Chia tầm nhìn thành các bước 90 ngày có thể đo được.', 'Bạn đang xây điều lớn, hay đang chờ đủ điều kiện để bắt đầu xây?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (22, 'tinh_yeu', 'Trong tình yêu, số 22 thường nghiêm túc, xây quan hệ như xây nền móng lâu dài.', 'Dễ đặt công việc/sứ mệnh lên trên người yêu.', 'Đặt lịch cố định cho hai người như một cam kết không dời.', 'Người ấy có chỗ trong kế hoạch lớn của bạn không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (22, 'gia_dinh', 'Số 22 thường là trụ cột, người lo nền tảng lâu dài cho gia đình.', 'Dễ nghiêm khắc, coi gia đình như một dự án cần quản lý.', 'Để gia đình có những lúc không có mục tiêu gì cả.', 'Gia đình bạn cần một người quản lý, hay một người ở cạnh?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (22, 'con_cai', 'Là cha mẹ, số 22 thường xây cho con nền tảng vững: học hành, kỷ luật, tương lai.', 'Dễ đặt kỳ vọng quá lớn, vạch sẵn đường cho con.', 'Hỏi con muốn gì trước khi lập kế hoạch cho con.', 'Kế hoạch cho con là của con, hay của bạn?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (22, 'tre_em', 'Trẻ số 22 thường chín chắn sớm, thích xây dựng, có tổ chức.', 'Dễ tự tạo áp lực, sợ thất bại.', 'Khen trẻ khi thử và sai, không chỉ khi thành công.', 'Trẻ có dám làm hỏng một thứ mà không sợ không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (22, 'su_nghiep', 'Số 22 thường hợp việc xây hệ thống lớn: kiến trúc, kỹ thuật, điều hành tổ chức, chính sách, khởi nghiệp quy mô.', 'Dễ ôm đồm, khó giao việc; cầu toàn làm chậm tiến độ.', 'Xây đội ngũ và quy trình để việc lớn không phụ thuộc vào một mình bạn.', 'Nếu bạn nghỉ một tháng, việc của bạn có chạy không?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
