insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (33, 'suc_khoe', 'Số 33 thường bền bỉ khi phục vụ, dễ quên bản thân.', 'Dễ kiệt sức vì chăm người khác; căng thẳng âm thầm.', 'Nhờ giúp đỡ trước khi quá tải.', 'Lần cuối bạn nhờ ai giúp là khi nào?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (33, 'ban_be_xa_hoi', 'Số 33 thường là người bạn bao dung, ai cũng muốn tìm đến.', 'Dễ bị lợi dụng, khó từ chối.', 'Tập nói ''lần này mình không giúp được''.', 'Có mối quan hệ nào chỉ tồn tại vì bạn luôn cho đi?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_linh_vuc_nghia (gia_tri, linh_vuc, xu_huong, mat_toi, goi_y, cau_tu_soi, trang_thai, source_id, school_id) values (33, 'cuoc_song', 'Số 33 thường muốn nhà là nơi đón mọi người, ấm áp, rộng cửa.', 'Dễ để nhà thành chốn của người khác, mất góc riêng.', 'Giữ một không gian chỉ của riêng bạn.', 'Trong nhà bạn, đâu là chỗ chỉ để bạn nghỉ?', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (gia_tri, linh_vuc, source_id, school_id) do update set xu_huong = excluded.xu_huong, mat_toi = excluded.mat_toi, goi_y = excluded.goi_y, cau_tu_soi = excluded.cau_tu_soi;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-1', 'Cùng chủ động, cùng thích làm, dễ bắt nhịp khi chung mục tiêu.', 'Hai người cùng muốn cầm lái — dễ tranh quyền quyết định.', 'Chia rõ lĩnh vực mỗi người được quyết cuối cùng.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-2', 'Một người mở đường, một người giữ hoà khí — dễ bổ sung cho nhau.', 'Số 1 dễ quyết thay, số 2 dễ nhịn rồi tủi.', 'Số 1 hỏi ý trước; số 2 nói ra điều mình muốn thay vì chờ được đoán.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-3', 'Năng lượng cao, nhiều ý tưởng, vui khi cùng làm việc mới.', 'Số 1 muốn tiến nhanh theo một hướng, số 3 dễ rẽ nhánh.', 'Chốt một mục tiêu chung mỗi quý và cùng giữ nó.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-4', 'Một người khởi xướng, một người xây nền — bộ đôi làm được việc.', 'Số 1 thấy số 4 chậm, số 4 thấy số 1 liều.', 'Thống nhất ''thử nhỏ trước, làm lớn sau'' cho mọi kế hoạch mới.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-5', 'Cùng thích tự do, dám thử, ít ràng buộc nhau.', 'Cả hai khó cam kết lâu dài, dễ mỗi người một hướng.', 'Có những nghi thức chung cố định giữa hai lối sống tự do.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-6', 'Số 1 mang hướng đi, số 6 mang sự chăm lo — có người lo hướng đi, có người lo con người.', 'Số 1 thấy bị quản, số 6 thấy mình không được ghi nhận.', 'Số 1 nói lời cảm ơn cụ thể; số 6 để số 1 tự quyết phần của họ.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-7', 'Cả hai độc lập, tôn trọng khoảng riêng.', 'Ít chia sẻ cảm xúc; dễ sống song song thay vì cùng nhau.', 'Một buổi mỗi tuần kể cho nhau điều mình đang nghĩ thật.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-8', 'Cùng tham vọng, cùng hướng kết quả — mạnh khi chung mục tiêu.', 'Hai cái tôi lớn, tranh quyền lực, cạnh tranh ngầm.', 'Chọn chung một ''đối thủ'' bên ngoài thay vì đấu nhau; tách vai rõ.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('1-9', 'Số 1 hành động, số 9 truyền cảm hứng — dễ làm việc có ý nghĩa cùng nhau.', 'Số 1 thấy số 9 mơ hồ, số 9 thấy số 1 ích kỷ.', 'Cùng làm một dự án vừa có kết quả đo được vừa có ý nghĩa.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('2-2', 'Rất hiểu nhau, dịu dàng, ít va chạm lớn.', 'Cả hai né xung đột, chuyện nhỏ tích tụ thành khoảng cách.', 'Hẹn định kỳ nói thẳng một điều chưa hài lòng.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('2-3', 'Số 2 lắng nghe, số 3 kể chuyện — không khí vui, ấm.', 'Số 3 vô tư, số 2 dễ tổn thương vì câu đùa.', 'Số 3 hỏi ''câu đó có làm bạn buồn không?''; số 2 nói ra ngay.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('2-4', 'Ổn định, trung thành, đều đặn — hợp cùng xây điều lâu dài.', 'Dễ nhàm, ít bất ngờ; số 4 khô khan với nhu cầu được quan tâm của số 2.', 'Lên lịch những điều bất ngờ nho nhỏ.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('2-5', 'Số 5 mang không khí mới, số 2 mang sự ấm áp.', 'Số 2 cần gắn bó, số 5 cần tự do — dễ hiểu lầm là hết thương.', 'Nói rõ nhu cầu khoảng riêng và nhu cầu kết nối bằng con số cụ thể (bao nhiêu tối/tuần).', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('2-6', 'Cả hai chu đáo, biết lo cho nhau — rất ấm.', 'Cả hai cho nhiều, ít đòi; oán thầm khi không được đáp lại.', 'Mỗi người nói một nhu cầu của mình mỗi tuần.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('2-7', 'Yên tĩnh, sâu sắc, tôn trọng nhau.', 'Số 2 cần gần, số 7 cần xa — dễ thấy bị bỏ rơi.', 'Số 7 báo trước khi cần ở một mình; số 2 có hoạt động riêng lúc đó.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('2-8', 'Số 8 lo đường lớn, số 2 lo sự gắn kết — bổ sung tốt.', 'Số 8 dễ át, số 2 dễ im.', 'Quyết định lớn luôn cần cả hai đồng ý.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('2-9', 'Cùng giàu lòng thương, dễ đồng cảm.', 'Cả hai dễ hy sinh, dễ mơ hồ về tiền bạc và trách nhiệm.', 'Lập kế hoạch tài chính chung rõ ràng.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('3-3', 'Vui, sáng tạo, nhiều chuyện để nói.', 'Cả hai tản mạn, thiếu người lo việc thực tế.', 'Chia việc thực tế theo lịch, có danh sách chung.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('3-4', 'Số 3 mang niềm vui, số 4 mang sự chắc chắn.', 'Số 4 thấy số 3 thiếu trách nhiệm, số 3 thấy số 4 cứng.', 'Số 3 giữ lời hứa nhỏ; số 4 chừa chỗ cho ngẫu hứng.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('3-5', 'Năng động, vui, thích trải nghiệm — ít buồn chán.', 'Thiếu ổn định, dễ chi tiêu và bỏ dở cùng nhau.', 'Đặt mục tiêu chung dài hạn và một người giữ ngân sách.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('3-6', 'Số 3 làm không khí vui, số 6 làm không khí ấm.', 'Số 6 dễ chăm và nhắc quá mức, số 3 thấy bị gò.', 'Số 6 bớt nhắc; số 3 chủ động nhận phần việc chung.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('3-7', 'Số 3 kéo số 7 ra ngoài, số 7 giúp số 3 sâu hơn.', 'Số 3 thấy số 7 lạnh, số 7 thấy số 3 hời hợt.', 'Xen kẽ hoạt động đông vui và hoạt động yên tĩnh.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('3-8', 'Số 3 giỏi truyền đạt, số 8 giỏi tổ chức — hợp làm ăn.', 'Số 8 thấy số 3 thiếu nghiêm túc; số 3 thấy số 8 thực dụng.', 'Chia vai: số 3 lo đối ngoại, số 8 lo vận hành.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('3-9', 'Giàu cảm xúc, cùng yêu cái đẹp và những điều có ý nghĩa.', 'Cả hai ít thực tế, dễ bỏ qua việc cần làm.', 'Mỗi tháng rà soát việc thực tế (tiền, giấy tờ) cùng nhau.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('4-4', 'Rất ổn định, có kế hoạch, đáng tin với nhau.', 'Cứng nhắc, ít thay đổi, dễ nhàm.', 'Mỗi năm cùng thử một điều mới.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('4-5', 'Số 4 cho nền, số 5 cho gió — học được nhiều từ nhau.', 'Số 4 thấy số 5 thiếu ổn định, số 5 thấy số 4 gò bó.', 'Thống nhất phần ''cố định'' và phần ''linh hoạt'' trong đời sống chung.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('4-6', 'Cùng trách nhiệm, cùng lo cho người xung quanh, xây nền vững.', 'Nhiều bổn phận, ít vui chơi.', 'Có những buổi chỉ để vui, không bàn việc phải làm.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('4-7', 'Cùng nghiêm túc, cẩn trọng, tôn trọng lý lẽ.', 'Khô khan, ít biểu lộ tình cảm.', 'Tập nói lời cảm xúc thành câu, không chỉ hành động.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('4-8', 'Bộ đôi thực tế, giỏi xây tài sản và sự nghiệp.', 'Cuốn vào công việc, quên tình cảm.', 'Tách thời gian riêng tư khỏi thời gian bàn chuyện tiền.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('4-9', 'Số 4 hiện thực hoá lý tưởng của số 9.', 'Số 9 thấy số 4 thiếu tầm nhìn; số 4 thấy số 9 viển vông.', 'Số 9 nêu mục đích, số 4 lập kế hoạch — cả hai cùng duyệt.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('5-5', 'Tự do, sôi nổi, nhiều trải nghiệm chung.', 'Thiếu ổn định, khó cam kết, khó giữ nề nếp.', 'Có vài cam kết cố định dù sống linh hoạt.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('5-6', 'Số 5 mang sự mới mẻ, số 6 mang mái ấm.', 'Số 6 muốn giữ, số 5 muốn đi.', 'Số 5 báo trước kế hoạch; số 6 tôn trọng khoảng tự do đã thoả thuận.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('5-7', 'Cùng tò mò, thích khám phá (số 5 ra ngoài, số 7 vào trong).', 'Nhịp sống khác nhau, khó chung thời gian.', 'Chọn trải nghiệm vừa phiêu lưu vừa có chiều sâu (du lịch văn hoá, học chung).', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('5-8', 'Năng động, dám làm, hợp làm ăn.', 'Cả hai liều, dễ quyết nhanh sai lớn.', 'Mọi quyết định tiền lớn cần một ngày chờ và một người thứ ba góp ý.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('5-9', 'Cùng mở rộng, thích đi xa, rộng lượng.', 'Thiếu gốc rễ, ít tích luỹ.', 'Có mục tiêu tích luỹ chung và một nơi ''về'' cố định.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('6-6', 'Rất chu đáo, hướng gia đình, ấm cúng.', 'Cả hai muốn chăm, dễ kiểm soát nhau, mệt vì trách nhiệm.', 'Luân phiên người được chăm, người đi chăm.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('6-7', 'Số 6 mang sự ấm, số 7 mang chiều sâu.', 'Số 6 thấy bị đẩy ra, số 7 thấy bị xâm phạm.', 'Thoả thuận về khoảng riêng và cách hỏi han.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('6-8', 'Số 8 lo vật chất, số 6 lo tinh thần — gia đình vững.', 'Số 8 vắng mặt, số 6 thấy cô đơn trong trách nhiệm.', 'Số 8 có mặt ở những dịp quan trọng như một cam kết công việc.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('6-9', 'Cùng giàu lòng thương, thích giúp người.', 'Lo cho người ngoài nhiều, quên nhau.', 'Dành thời gian cho riêng hai người trước việc chung.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('7-7', 'Hiểu nhau không cần nói nhiều, tôn trọng không gian riêng.', 'Quá khép kín, xa cách dần.', 'Cùng một sở thích trí tuệ để có chuyện chung.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('7-8', 'Số 7 phân tích, số 8 quyết — hợp làm việc lớn.', 'Số 8 thấy số 7 chậm, số 7 thấy số 8 vội.', 'Số 7 đưa phân tích có hạn chót; số 8 chờ đủ hạn.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('7-9', 'Cùng hướng về ý nghĩa, tinh thần, tri thức.', 'Cả hai xa thực tế.', 'Cùng lập kế hoạch thực tế cho những điều cả hai tin.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('8-8', 'Cùng tham vọng, xây được nhiều.', 'Tranh quyền, cạnh tranh, cuốn vào tiền bạc.', 'Tách vai trò rõ; đặt mục tiêu chung phi tài chính.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('8-9', 'Số 8 có nguồn lực, số 9 có lý tưởng — có thể làm việc lớn có ích.', 'Số 9 thấy số 8 thực dụng; số 8 thấy số 9 hoang phí.', 'Cùng quyết một phần thu nhập cho việc ý nghĩa, phần còn lại tích luỹ.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_cap_so (cap, hoa, va, cung_lam, trang_thai, source_id, school_id) values ('9-9', 'Rộng lượng, lý tưởng, hiểu nhau về giá trị sống.', 'Cả hai dễ bỏ bê việc thực tế và bản thân.', 'Có người giữ vai trò lo việc thực tế theo từng tháng.', 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (cap, source_id, school_id) do update set hoa = excluded.hoa, va = excluded.va, cung_lam = excluded.cung_lam;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '1', '{"y_nghia": "Thể hiện bản thân, nói ra điều mình nghĩ.", "thieu": "Dễ khó nói ra cảm xúc, người khác phải đoán ý.", "mot": "Diễn đạt vừa phải, đôi khi khó nói điều sâu kín.", "hai": "Diễn đạt cân bằng, nói được cả lý lẽ lẫn cảm xúc.", "ba_tro_len": "Nói nhiều, dễ lấn át hoặc thu mình khi không được nghe; cần tập nghe."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '2', '{"y_nghia": "Trực giác, độ nhạy với cảm xúc người khác.", "thieu": "Dễ vô tình không để ý cảm xúc người xung quanh.", "mot": "Nhạy cảm vừa phải, đọc được không khí.", "hai": "Trực giác tốt, dễ đoán người khác nghĩ gì.", "ba_tro_len": "Rất nhạy, dễ tổn thương, dễ bị cảm xúc người khác cuốn theo."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '3', '{"y_nghia": "Tư duy, trí nhớ, óc tưởng tượng.", "thieu": "Dễ quên việc ngắn hạn; cần ghi chép.", "mot": "Tư duy tốt, thích học hỏi.", "hai": "Tư duy nhanh, giàu ý tưởng, đôi khi xa thực tế.", "ba_tro_len": "Sống nhiều trong đầu, dễ lo nghĩ quá mức."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '4', '{"y_nghia": "Thực tế, trật tự, làm việc bằng tay.", "thieu": "Dễ thiếu kiên nhẫn với việc chi tiết, tổ chức.", "mot": "Có óc thực tế, làm việc gọn.", "hai": "Rất thực tế, giỏi tổ chức, có thể cứng nhắc.", "ba_tro_len": "Nặng về vật chất và quy tắc, khó linh hoạt."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '5', '{"y_nghia": "Cảm xúc, tự do, sức bật (ô trung tâm).", "thieu": "Dễ thiếu động lực, khó thể hiện tình cảm; cần tìm điều làm mình hào hứng.", "mot": "Cân bằng cảm xúc, có động lực.", "hai": "Nhiều năng lượng, quyết liệt, đôi khi bốc đồng.", "ba_tro_len": "Cảm xúc mạnh, dễ nóng, cần kênh xả năng lượng."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '6', '{"y_nghia": "Sáng tạo, trách nhiệm với gia đình, tổ ấm.", "thieu": "Dễ ít gắn bó nhà cửa hoặc chưa tìm được nơi thuộc về.", "mot": "Yêu gia đình, có óc sáng tạo.", "hai": "Lo cho gia đình nhiều, dễ lo lắng.", "ba_tro_len": "Dễ lo âu, kiểm soát người thân vì lo."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '7', '{"y_nghia": "Học qua trải nghiệm, kể cả mất mát.", "thieu": "Dễ lặp lại bài học cũ vì chưa rút ra được.", "mot": "Học được từ trải nghiệm của mình.", "hai": "Trải nghiệm nhiều thăng trầm, trưởng thành qua đó.", "ba_tro_len": "Đời nhiều bài học khó; cần chăm sóc tinh thần kỹ."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '8', '{"y_nghia": "Độc lập, sự tinh tế trong xử lý việc.", "thieu": "Dễ thiếu kiên nhẫn với chi tiết, cần người hỗ trợ.", "mot": "Chu đáo, có trách nhiệm với việc mình làm.", "hai": "Tinh tế, độc lập, hay tự làm lấy.", "ba_tro_len": "Dễ cầu toàn, khó chịu khi mọi thứ không theo ý."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('o_so', '9', '{"y_nghia": "Lý tưởng, tham vọng, trách nhiệm với cộng đồng.", "thieu": "(Hiếm — người sinh 19xx luôn có số 9.) Có thể thiếu động lực hướng ngoại.", "mot": "Có lý tưởng, muốn làm điều có ích.", "hai": "Tham vọng rõ, dễ đặt tiêu chuẩn cao cho người khác.", "ba_tro_len": "Lý tưởng rất cao, dễ phê phán, khó hài lòng."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_du', '1-2-3', '{"ten": "Mũi tên Kế hoạch", "y_nghia": "Có xu hướng lập kế hoạch, sắp xếp trước khi làm.", "mat_toi": "Dễ ghét bất ngờ, khó chịu khi người khác làm không theo kế hoạch."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_du', '4-5-6', '{"ten": "Mũi tên Ý chí", "y_nghia": "Được mô tả là có ý chí mạnh, đã quyết là làm.", "mat_toi": "Dễ cứng đầu, khó nghe khuyên."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_du', '7-8-9', '{"ten": "Mũi tên Hành động", "y_nghia": "Thích bắt tay vào làm, học bằng làm.", "mat_toi": "Dễ bồn chồn khi phải chờ, làm trước nghĩ sau."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_du', '3-6-9', '{"ten": "Mũi tên Trí tuệ", "y_nghia": "Tư duy tốt, trí nhớ tốt, thích học.", "mat_toi": "Dễ coi thường người chậm hiểu, sống nhiều trong đầu."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_du', '2-5-8', '{"ten": "Mũi tên Cảm xúc", "y_nghia": "Cảm xúc cân bằng, hiểu người, dễ tạo thiện cảm.", "mat_toi": "Dễ ôm cảm xúc của người khác."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_du', '1-4-7', '{"ten": "Mũi tên Thực tế", "y_nghia": "Khéo tay, thực tế, giỏi việc cụ thể.", "mat_toi": "Dễ coi trọng vật chất, ngại điều trừu tượng."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_du', '1-5-9', '{"ten": "Mũi tên Quyết tâm", "y_nghia": "Được mô tả là kiên định, theo đuổi mục tiêu tới cùng.", "mat_toi": "Dễ bướng, bỏ qua tín hiệu nên dừng."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_du', '3-5-7', '{"ten": "Mũi tên Tâm linh", "y_nghia": "Nhạy bén, có chiều sâu nội tâm, hay tìm ý nghĩa.", "mat_toi": "Dễ mơ hồ, xa rời thực tế."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_trong', '1-2-3', '{"ten": "Mũi tên trống Kế hoạch", "y_nghia": "Dễ làm theo cảm hứng, ít lập kế hoạch.", "goi_y": "Thử lập kế hoạch cho một tuần và xem điều gì thay đổi."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_trong', '4-5-6', '{"ten": "Mũi tên trống Ý chí (Uất giận)", "y_nghia": "Dễ thất vọng khi mọi việc không như ý, bực bội dồn nén.", "goi_y": "Tìm cách xả cảm xúc lành mạnh; đặt kỳ vọng nhỏ hơn cho từng bước."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_trong', '7-8-9', '{"ten": "Mũi tên trống Hành động (Thụ động)", "y_nghia": "Dễ chần chừ bắt đầu, chờ điều kiện hoàn hảo.", "goi_y": "Bắt đầu bằng việc nhỏ nhất có thể làm ngay trong 5 phút."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mui_ten_trong', '3-6-9', '{"ten": "Mũi tên trống Trí tuệ (Trí nhớ ngắn hạn)", "y_nghia": "Dễ quên việc vặt, cần hệ thống ghi nhớ.", "goi_y": "Dùng danh sách, lịch nhắc; học bằng lặp lại có khoảng cách."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
