insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('ngay_ca_nhan', '4', '"Ngày cá nhân 4: hợp làm việc chi tiết, dọn việc tồn."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
