insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('ngay_ca_nhan', '9', '"Ngày cá nhân 9: hợp hoàn tất, buông, cho đi."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('no_nghiep', '13', '{"ten": "Nợ nghiệp 13 (13/4)", "y_nghia": "Trong truyền thống thần số, 13 gắn với bài học về kỷ luật và kiên trì: dễ muốn đường tắt, nản khi việc lâu.", "goi_y": "Chọn một việc dài hơi và làm đều mỗi ngày; đây là bài học về thói quen, không phải điều bị áp đặt."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('no_nghiep', '14', '{"ten": "Nợ nghiệp 14 (14/5)", "y_nghia": "14 gắn với bài học về chừng mực và tự do có trách nhiệm: dễ sa đà, thiếu điều độ.", "goi_y": "Đặt giới hạn rõ cho những thứ dễ sa đà (chi tiêu, ăn uống, màn hình)."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('no_nghiep', '16', '{"ten": "Nợ nghiệp 16 (16/7)", "y_nghia": "16 gắn với bài học về cái tôi: dễ gặp đổ vỡ khi quá tự mãn, rồi phải dựng lại.", "goi_y": "Chủ động xin phản hồi thẳng từ người tin cậy mỗi quý."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('no_nghiep', '19', '{"ten": "Nợ nghiệp 19 (19/1)", "y_nghia": "19 gắn với bài học về độc lập và nhờ giúp: dễ ôm hết một mình, khó nhận hỗ trợ.", "goi_y": "Tập nhờ giúp một việc nhỏ mỗi tuần."}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '1', '"Tên thiếu số 1: bài học về tự tin, dám đứng ra nói điều mình muốn."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '2', '"Tên thiếu số 2: bài học về kiên nhẫn, hợp tác, để ý cảm xúc người khác."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '3', '"Tên thiếu số 3: bài học về thể hiện bản thân, bớt tự chỉ trích."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '4', '"Tên thiếu số 4: bài học về kỷ luật, làm việc có hệ thống."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '5', '"Tên thiếu số 5: bài học về thích nghi, dám thay đổi, dám trải nghiệm."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '6', '"Tên thiếu số 6: bài học về trách nhiệm trong gia đình và các mối quan hệ."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '7', '"Tên thiếu số 7: bài học về đào sâu, tin vào hiểu biết của chính mình."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '8', '"Tên thiếu số 8: bài học về quản lý tiền bạc và quyền hạn."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('bai_hoc_nghiep', '9', '"Tên thiếu số 9: bài học về bao dung, nhìn rộng hơn lợi ích của mình."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'cach_tinh_duong_doi', '{"tieu_de": "Cách tính số chủ đạo (đường đời)", "noi_dung": "Cộng tất cả chữ số của ngày, tháng, năm sinh dương lịch rồi rút gọn tới khi còn một chữ số. Riêng 11, 22, 33 là số cái, được giữ nguyên. Ví dụ 24/10/1988: 2+4+1+0+1+9+8+8 = 33 → giữ 33.", "tu_khoa": ["so chu dao tinh", "duong doi tinh", "tinh so chu dao", "so chu dao la gi"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'chu_dao_la_duong_doi', '{"tieu_de": "Số chủ đạo và đường đời", "noi_dung": "Hai tên gọi cùng một chỉ số. Sách tiếng Việt phổ biến gọi là ''số chủ đạo'', sách dịch từ tiếng Anh (Life Path) gọi là ''đường đời''.", "tu_khoa": ["so chu dao va duong doi"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'am_duong_lich', '{"tieu_de": "Âm lịch hay dương lịch?", "noi_dung": "Thần số học Pythagoras dùng ngày dương lịch (lịch Gregory). Dùng ngày âm sẽ ra con số khác và không thuộc hệ này. Nếu giấy tờ ghi ngày âm, hãy đổi sang dương trước khi tính.", "tu_khoa": ["ngay am hay", "am hay duong", "tinh theo ngay am", "tinh theo am lich"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'gio_ty', '{"tieu_de": "Sinh lúc 23 giờ tính ngày nào?", "noi_dung": "Với thần số học, sản phẩm này tính sinh 23:00–23:59 vẫn thuộc ngày hôm đó (không sang ngày mới). Tử vi thì theo quy ước khác (23:00 đã sang ngày mới), nên người sinh giờ này có thể thấy hai hệ lệch ngày nhau.", "tu_khoa": ["sinh luc 23", "23 gio thi", "23h thi", "gio ty tinh"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'khac_trang', '{"tieu_de": "Vì sao trang khác ra số khác?", "noi_dung": "Mỗi trang chọn quy ước khác nhau: giữ hay không giữ số 33, chữ Y là nguyên âm hay phụ âm, chữ Đ tính ra sao, cộng gộp hay cộng từng phần ngày/tháng/năm. Với tên tiếng Việt, đổi quy ước có thể đổi con số. Trang này dùng một quy ước cố định và ghi chú khi con số nhạy với cách viết tên.", "tu_khoa": ["trang khac", "web khac", "ra so khac", "ung dung khac"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'so_cai', '{"tieu_de": "Số cái (11, 22, 33) là gì?", "noi_dung": "Là các số không rút gọn tiếp khi tính. Truyền thống coi chúng là phiên bản ''cường độ cao'' của 2, 4, 6. Nhiều trang Việt chỉ giữ 11 và 22, rút 33 về 6; trang này giữ cả 33. Số cái không phải là ''người được chọn'' — tỷ lệ người mang số chủ đạo 11 là khoảng 9–10% dân số.", "tu_khoa": ["so cai la gi", "33 co duoc", "rut ve 6", "22/4", "so cai 11 22 33"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'ba_chi_so_ten', '{"tieu_de": "Sứ mệnh, linh hồn, nhân cách khác nhau thế nào?", "noi_dung": "Cả ba tính từ họ tên. Sứ mệnh: cộng mọi chữ cái. Linh hồn: chỉ nguyên âm — điều bạn khao khát bên trong. Nhân cách: chỉ phụ âm — ấn tượng bạn tạo cho người khác.", "tu_khoa": ["su menh linh hon nhan cach"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'nam_ca_nhan', '{"tieu_de": "Năm cá nhân tính thế nào?", "noi_dung": "Rút gọn ngày sinh + tháng sinh + năm đang xem, được một số từ 1 đến 9. Chu kỳ lặp lại mỗi 9 năm. Trang này tính theo mốc 1/1; có trường phái đổi năm vào ngày sinh nhật, hai cách lệch nhau ở quãng đầu năm.", "tu_khoa": ["nam ca nhan tinh", "tinh nam ca nhan", "tu 1/1 hay", "nam ca nhan doi tu khi nao", "tinh tu 1/1"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'thang_ngay_ca_nhan', '{"tieu_de": "Tháng và ngày cá nhân", "noi_dung": "Tháng cá nhân = năm cá nhân + tháng đang xem, rút về 1–9. Ngày cá nhân = tháng cá nhân + ngày đang xem, rút về 1–9.", "tu_khoa": ["cach tinh thang ca nhan", "cach tinh ngay ca nhan", "thang ca nhan tinh", "ngay ca nhan tinh"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'dinh_cao_thu_thach', '{"tieu_de": "Đỉnh cao và thử thách", "noi_dung": "Đỉnh cao chia đời thành 4 giai đoạn theo tuổi, mỗi giai đoạn một con số chủ đề; đỉnh 1 kết thúc ở tuổi 36 trừ số chủ đạo. Thử thách là bài học khó lặp lại, tính từ hiệu các phần ngày/tháng/năm sinh. Nhiều trang gọi là ''kim tự tháp thần số''.", "tu_khoa": ["dinh cao va thu thach la gi", "dinh cao la gi", "thu thach la gi"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'bieu_do', '{"tieu_de": "Biểu đồ ngày sinh", "noi_dung": "Lưới 3×3 xếp các chữ số trong ngày sinh (bỏ số 0): hàng trên 3-6-9, giữa 2-5-8, dưới 1-4-7. Ô có số cho biết thế mạnh được nhấn, ô trống là điều cần học thêm.", "tu_khoa": ["bieu do ngay sinh la gi"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'mui_ten', '{"tieu_de": "Mũi tên trong biểu đồ", "noi_dung": "Ba ô thẳng hàng cùng có số tạo thành ''mũi tên'' (ví dụ 1-5-9 là mũi tên Quyết tâm); ba ô cùng trống tạo ''mũi tên trống'' (1-5-9 trống là mũi tên Trì hoãn). Có 8 đường: 3 hàng, 3 cột, 2 chéo.", "tu_khoa": ["mui ten trong than so hoc la gi", "bao nhieu mui ten", "mui ten la gi"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'chi_so_phu', '{"tieu_de": "Số thái độ, trưởng thành, ngày sinh", "noi_dung": "Số thái độ = ngày + tháng sinh, là ấn tượng đầu tiên bạn tạo ra. Số trưởng thành = số chủ đạo + sứ mệnh, là hướng đời nghiêng về sau tuổi 35–40. Số ngày sinh = ngày trong tháng rút gọn, là một tài năng phụ.", "tu_khoa": ["so thai do la gi", "so truong thanh la gi", "so ngay sinh khac so chu dao"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'chu_y', '{"tieu_de": "Chữ Y là nguyên âm hay phụ âm?", "noi_dung": "Trang này dùng quy tắc cố định: Y là nguyên âm khi đứng riêng không liền kề nguyên âm khác trong cùng âm tiết (vd ''Ly'', ''Vy''); kề nguyên âm khác thì là phụ âm (vd ''Nguyễn'', ''Huy''). Chỉ ảnh hưởng số linh hồn và nhân cách.", "tu_khoa": ["chu y la nguyen am"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'dau_tieng_viet', '{"tieu_de": "Dấu, chữ Đ và tên khai sinh", "noi_dung": "Bỏ dấu thanh và dấu mũ (ư→u, ơ→o, â→a), chữ Đ tính như D. Nên dùng tên khai sinh đầy đủ; tên thường gọi hay biệt danh có thể ra số khác — trang ghi chú khi điều đó xảy ra.", "tu_khoa": ["co dau va khong dau", "ten khai sinh hay ten thuong goi", "chu d thi tinh", "u o a tinh the nao", "khi bo dau"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'no_nghiep', '{"tieu_de": "Nợ nghiệp tính thế nào?", "noi_dung": "Nếu trong quá trình rút gọn ngày sinh, số chủ đạo hoặc các số tên xuất hiện 13, 14, 16 hay 19 thì gọi là ''nợ nghiệp''. Đây là cách truyền thống gọi tên một bài học lặp lại, không phải hình phạt hay quả báo.", "tu_khoa": ["no nghiep tinh the nao"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'so_xui', '{"tieu_de": "Có số xui, số xấu không?", "noi_dung": "Thần số học Pythagoras không có số xui hay số xấu: mỗi số 1–9 (và 11, 22, 33) đều có mặt mạnh và mặt tối. Nỗi sợ số 13 đến từ văn hoá phương Tây, số 4 từ cách đọc gần chữ ''tử'' trong tiếng Hán — đều không thuộc hệ này. Riêng 13 trong thần số được gọi là ''nợ nghiệp 13/4'' khi nó xuất hiện lúc rút gọn số chủ đạo hay số tên: gợi bài học về kỷ luật và kiên trì, không phải điềm rủi. Biển số xe, số nhà, số điện thoại 13 không nói gì về vận may của bạn.", "tu_khoa": ["so 13", "so xui", "so xau", "so 4 (co )?xui", "so 4 (co )?xau", "so nao xui", "con so xui"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'bai_hoc_nghiep', '{"tieu_de": "Bài học nghiệp tính thế nào?", "noi_dung": "Là các chữ số từ 1 đến 9 không xuất hiện trong giá trị chữ cái của họ tên. Mỗi số vắng mặt gợi một kỹ năng cần rèn thêm.", "tu_khoa": ["bai hoc nghiep tinh the nao"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'so_0_29_2', '{"tieu_de": "Số 0 và người sinh 29/2", "noi_dung": "Số 0 không tính trong biểu đồ ngày sinh (không có ô cho 0) nhưng vẫn góp vào phép cộng. Người sinh 29/2 tính bình thường với ngày 29 tháng 2; năm cá nhân vẫn dùng ngày 29 tháng 2.", "tu_khoa": ["so 0 trong ngay sinh", "29/2 thi"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'khong_doi', '{"tieu_de": "Số chủ đạo có đổi theo thời gian không?", "noi_dung": "Không. Số chủ đạo cố định từ ngày sinh. Thứ thay đổi theo thời gian là năm/tháng/ngày cá nhân và giai đoạn đỉnh cao.", "tu_khoa": ["co thay doi theo thoi gian"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'do_tin', '{"tieu_de": "Thần số học có chính xác, có khoa học không?", "noi_dung": "Thần số học là hệ biểu tượng văn hoá, không phải khoa học: chưa có nghiên cứu nào cho thấy con số dự đoán được tính cách hay sự kiện. Hệ đang dùng do các tác giả Mỹ (Balliett, Jordan…) dựng đầu thế kỷ 20, gắn tên Pythagoras phần nhiều mang tính biểu tượng. Dùng tốt nhất như một cái cớ để tự soi, không như sự thật về bạn.", "tu_khoa": ["co chinh xac khong", "co khoa hoc khong", "pythagoras", "tin hoan toan", "co phai me tin", "me tin khong"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'barnum', '{"tieu_de": "Vì sao ai đọc cũng thấy đúng?", "noi_dung": "Đó là hiệu ứng Barnum: mô tả đủ rộng thì ai cũng thấy mình trong đó. Vì vậy mỗi con số ở đây luôn kèm mặt tối và một câu tự kiểm — nếu bạn không trả lời được ''điều gì chứng tỏ tôi KHÔNG phải số này'', thì con số chưa nói gì về bạn.", "tu_khoa": ["barnum", "ai doc mo ta", "thay dung het"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'ty_le', '{"tieu_de": "Bao nhiêu người cùng số với tôi?", "noi_dung": "Mỗi số chủ đạo phổ biến chiếm khoảng 9–11% dân số (hàng trăm triệu người); số 2 và 22 hiếm hơn vì quy ước giữ số cái. Chuỗi năm cá nhân trùng khít với mọi người cùng ngày và tháng sinh (khoảng 1/366 dân số).", "tu_khoa": ["bao nhieu nguoi cung"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'kiem_chung', '{"tieu_de": "Tự kiểm chứng thế nào?", "noi_dung": "Viết ra trước những điều con số ''nói'' về một năm cụ thể trong quá khứ, rồi mới đối chiếu với nhật ký đời mình. Làm thêm với một bảng số của ngày sinh khác làm đối chứng: nếu bảng đối chứng cũng ''khớp'' ngang bảng thật thì con số không mang thông tin riêng về bạn.", "tu_khoa": ["tu kiem chung", "kiem chung than so"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'khac_tu_vi', '{"tieu_de": "Thần số học khác tử vi thế nào?", "noi_dung": "Tử vi lập lá số từ ngày giờ sinh âm lịch với hàng trăm sao, có truyền thống hàng thế kỷ ở Á Đông. Thần số học dùng ngày dương lịch và tên, chỉ khoảng 12 phạm trù số, hình thành ở Mỹ đầu thế kỷ 20.", "tu_khoa": ["khac tu vi"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'moi_sach_khac', '{"tieu_de": "Sao mỗi sách viết một kiểu?", "noi_dung": "Vì thần số học không có văn bản gốc chuẩn. Mỗi tác giả mô tả con số theo cách của mình. Nội dung ở đây là bản biên soạn tham khảo, có ghi nguồn.", "tu_khoa": ["moi sach viet"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'cung_ngay_khac_nguoi', '{"tieu_de": "Cùng ngày sinh sao khác nhau hoàn toàn?", "noi_dung": "Vì con số chỉ là một lăng kính rất thô: cùng ngày sinh là cùng số chủ đạo, nhưng gia đình, văn hoá, lựa chọn và trải nghiệm tạo nên con người nhiều hơn bất kỳ con số nào.", "tu_khoa": ["cung ngay sinh ma"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('giai_thich', 'tuyen_dung', '{"tieu_de": "Có dùng thần số học để tuyển dụng được không?", "noi_dung": "Không nên. Không có bằng chứng con số dự báo năng lực, và loại ứng viên vì ngày sinh là phân biệt đối xử. Hãy dùng mô tả công việc rõ, bài thử thực tế và phỏng vấn có cấu trúc.", "tu_khoa": ["dung de tuyen dung"]}'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mau', 'an_toan', '"Mình rất tiếc vì bạn đang phải trải qua điều này. Lúc này điều quan trọng nhất là bạn an toàn, và con số không phải là câu trả lời cho nỗi đau này. Nếu bạn đang nghĩ đến việc làm hại bản thân hoặc đang gặp nguy hiểm, hãy gọi ngay 115 (cấp cứu) hoặc 113 (công an); nếu liên quan đến trẻ em, gọi 111. Hãy nói chuyện với một người bạn tin tưởng ngay hôm nay — người thân, bạn bè, hoặc chuyên gia tâm lý. Bạn không phải một mình gánh chuyện này."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mau', 'may_rui', '"Thần số học không cho ra con số để đánh đề, xổ số hay cá cược, và trang này không đưa ra con số như vậy. Nếu bạn muốn, mình có thể cùng xem con số của bạn nói gì về cách bạn ra quyết định khi đứng trước rủi ro."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mau', 'du_doan_cu_the', '"Thần số học không trả lời được những câu hỏi dạng sự kiện cụ thể như ngày giờ, sống chết, thắng thua hay việc người khác chắc chắn sẽ làm gì — ai khẳng định được điều đó là đang bịa. Mình có thể giúp bạn nhìn lại cách bạn đang đối diện với chuyện này qua con số của chính bạn."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mau', 'suc_khoe_the_chat', '"Thần số học không chẩn đoán hay dự báo bệnh, và không thay được bác sĩ. Với câu hỏi về sức khoẻ thể chất, hãy hỏi cơ sở y tế. Nếu bạn muốn, mình có thể xem con số nói gì về cách bạn phản ứng với căng thẳng và chăm sóc bản thân."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mau', 'tuyen_dung', '"Trang này không dùng thần số học để đánh giá, tuyển chọn hay loại người trong công việc: không có bằng chứng con số dự báo năng lực, và loại người vì ngày sinh là phân biệt đối xử. Hãy dùng mô tả công việc rõ ràng, bài thử thực tế và phỏng vấn có cấu trúc."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mau', 'can_nguoi_kia', '"Để trả lời câu này mình cần ngày sinh (và nếu có, họ tên) của người kia. Bạn nhập vào ô ''Người thứ hai'' nhé. Lưu ý: nên hỏi ý người ấy trước khi xem giúp họ."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('mau', 'khong_ro', '"Mình chưa chắc bạn đang hỏi về khía cạnh nào. Bạn thử nói rõ hơn — về tính cách, tình cảm, công việc, gia đình hay thời điểm?"'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('luu_y', 'tai_chinh', '"Đây là góc nhìn văn hoá về thói quen với tiền, không phải lời khuyên đầu tư. Quyết định tài chính cần dựa trên số liệu thật và người có chuyên môn."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('luu_y', 'suc_khoe', '"Đây là góc nhìn văn hoá để bạn tự soi, không thay cho bác sĩ hay chuyên gia tâm lý. Nếu căng thẳng kéo dài, hãy tìm người có chuyên môn."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('luu_y', 'quyet_dinh', '"Con số không quyết thay bạn. Hãy dùng nó như một câu hỏi gợi mở, rồi quyết dựa trên thông tin thực tế của chính bạn."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('luu_y', 'thoi_diem', '"Năm/tháng/ngày cá nhân là nhịp biểu tượng giống nhau cho mọi người cùng ngày tháng sinh, không phải lời tiên tri về sự kiện."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('luu_y', 'tam_linh', '"Các khái niệm như nợ nghiệp là cách truyền thống gọi tên một bài học lặp lại, không phải hình phạt hay định mệnh."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('luu_y', 'ten_goi', '"Đổi tên không đổi được con người; nếu định đổi tên thật trên giấy tờ, hãy cân nhắc lý do thực tế trước."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
insert into thanso_kb_khoi (khoi, ma, noi_dung, trang_thai, source_id, school_id) values ('luu_y', 'con_cai', '"Con số của trẻ chỉ là góc tham khảo; trẻ thay đổi rất nhiều theo tuổi và môi trường, đừng để con số thành chiếc khuôn."'::jsonb, 'nhap_ai', 'nhap_ai_2026', 'pythagoras_vn') on conflict (khoi, ma, source_id, school_id) do update set noi_dung = excluded.noi_dung;
